      .exitOverride()
      .configureOutput({
        writeErr: () => {},
        writeOut: () => {},
      })
      .command('foo')
      .addOption(
        new commander.Option('-s, --silent', "Don't print anything").env(
          'SILENT',
        ),
      )
      .addOption(
