test('when error called with code and exitOverride then throws with code', () => {
  const program = new commander.Command();
  let errorThrown;
  program
    .exitOverride((err) => {
      errorThrown = err;
      throw err;
    })
    .configureOutput({
      writeErr: () => {},
    });

  const code = 'commander.test';
  expect(() => {
    program.error('Goodbye', { code });
  }).toThrow();
  expect(errorThrown.code).toEqual(code);
})

