test('when use options with option-argument then option values and sources reset', () => {
    const program = new commander.Command()
      .option('-f, --foo <value>')
      .option('-b, --bar <value>');

    program.parse(['--foo', 'FOO'], { from: 'user' });
    expect(program.opts()).toEqual({ foo: 'FOO' });
